@push('scripts')<script>
(()=>{const updateUrl=@json(route('admin.inventaris.update'));const csrf=@json(csrf_token());async function save(type,id,field,value){const r=await fetch(updateUrl,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({type,id,field,value})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.success)throw new Error(d.message||'Gagal menyimpan perubahan.');}
document.querySelectorAll('.inline-inventory').forEach(el=>{el.dataset.previous=el.value;el.addEventListener('change',async()=>{const old=el.dataset.previous;try{await save(el.dataset.type,el.dataset.id,el.dataset.field,el.value);el.dataset.previous=el.value;if(el.classList.contains('asset-quantity')){const row=el.closest('tr'),total=Number(row.querySelector('[data-field="jumlah_total"]').value),bad=Number(row.querySelector('[data-field="jumlah_rusak"]').value);row.querySelector('.asset-good').textContent=Math.max(0,total-bad);row.querySelector('[data-field="jumlah_rusak"]').max=total;}}catch(e){el.value=old;alert(e.message);}})});
document.getElementById('editKursiBtn')?.addEventListener('click',async()=>{const el=document.getElementById('jumlahKursiText'),v=prompt('Jumlah kursi laboratorium:',el.textContent.trim());if(v===null)return;try{await save('lab',{{ $lab->id_lab }},'jumlah_kursi',v);el.textContent=v;}catch(e){alert(e.message)}});
const modal=document.getElementById('pcModal'),text=document.getElementById('pcModalText'),title=document.getElementById('pcModalTitle'),help=document.getElementById('pcModalHelp'),fieldLabel=document.getElementById('pcModalLabel');let activeId=null,activeField=null;function dataFor(id){return document.querySelector(`#pcSpecValues [data-id="${CSS.escape(String(id))}"]`)}function open(id,field){activeId=String(id);activeField=field;const item=dataFor(id),isNote=field==='keterangan';title.textContent=(isNote?'Keterangan Tambahan PC #':'Spesifikasi PC #')+id;fieldLabel.textContent=isNote?'Keterangan tambahan':'Spesifikasi PC';help.textContent=isNote?'Tambahkan catatan kondisi, kendala, atau informasi lain. Area ini dapat diperbesar dengan menarik sudut kanan bawah.':'Tuliskan spesifikasi perangkat secara lengkap, misalnya prosesor, RAM, penyimpanan, dan sistem operasi.';text.placeholder=isNote?'Ketik keterangan secara lebih lengkap di sini…':'Contoh: Intel Core i5, RAM 8 GB, SSD 256 GB…';text.value=item?.dataset[isNote?'note':'spec']||'';modal.style.display='flex';modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';setTimeout(()=>text.focus(),40);}document.querySelectorAll('.pc-detail').forEach(b=>b.onclick=()=>open(b.dataset.id,'keterangan'));document.querySelectorAll('.pc-spec').forEach(b=>b.onclick=()=>open(b.dataset.id,'spesifikasi_pc'));function closeModal(){modal.style.display='none';modal.setAttribute('aria-hidden','true');document.body.style.overflow='';}document.getElementById('pcModalCancel').onclick=closeModal;modal.addEventListener('click',event=>{if(event.target===modal)closeModal()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal.style.display==='flex')closeModal()});document.getElementById('pcModalSave').onclick=async()=>{try{await save('meja',activeId,activeField,text.value);const item=dataFor(activeId);if(item)item.dataset[activeField==='keterangan'?'note':'spec']=text.value;closeModal();}catch(e){alert(e.message)}};
})();
</script>@endpush
@endsection
